#include "web_pages.h"

namespace web_pages {

std::string camera_settings_html() {
    return std::string(R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">)HTML") + common_style() + R"HTML(</head><body><div class="top"><nav class="nav"><span class="brand">摄像头参数调整</span><a class="back" href="/" onclick="stopPreview()">返回服务选择</a></nav></div><main class="wrap"><div class="grid"><section class="panel"><h2>实时原始图像</h2><div class="live-stage"><div class="live"><img id="cameraLive" alt="摄像头实时图像"></div></div><p class="muted">使用 g_yuyv 原始 YUYV 图像；仅页面活跃期间取帧，离开后最多 3 秒自动停止。</p></section><section class="panel"><h2>曝光参数</h2><label>曝光模式</label><div class="row"><select id="autoExposure" onchange="toggleManual()"><option value="true">自动曝光</option><option value="false">手动曝光</option></select></div><label for="exposureTime">手动曝光时间</label><div class="row"><input id="exposureTime" type="number"><span id="exposureRange" class="muted"></span></div><label>自动曝光策略</label><div class="row"><select id="autoPriority"><option value="false">帧率优先</option><option value="true">亮度优先</option></select></div><button id="applyExposureButton" class="primary" onclick="applyExposureSettings()">应用并保存曝光参数</button><p id="cameraMessage" class="muted"></p></section></div><section class="panel" style="margin-top:16px"><h2>画面参数</h2><div id="imageControlList"><div class="setting-group" data-key="brightness"><label>亮度</label><p>调整画面整体明暗；过高容易使亮部发白，过低会丢失暗部细节。</p><div class="row"><input type="number"><span class="range"></span></div></div><div class="setting-group" data-key="contrast"><label>对比度</label><p>调整明暗区域之间的差异；增大后轮廓更鲜明，但可能损失灰度层次。</p><div class="row"><input type="number"><span class="range"></span></div></div><div class="setting-group" data-key="saturation"><label>饱和度</label><p>调整颜色浓度；数值越高颜色越鲜艳，越低越接近灰色。</p><div class="row"><input type="number"><span class="range"></span></div></div><div class="setting-group" data-key="hue"><label>色相</label><p>整体偏移画面颜色，用于修正偏色；通常保持默认值。</p><div class="row"><input type="number"><span class="range"></span></div></div><div class="setting-group" data-key="auto_white_balance"><label>自动白平衡</label><p>自动校正不同光源下的色温；关闭后可手动设置白平衡温度。</p><div class="row"><select onchange="toggleWhiteBalance()"><option value="1">开启</option><option value="0">关闭</option></select></div></div><div class="setting-group" data-key="gamma"><label>伽马</label><p>调整中间亮度层次，主要影响非纯黑、纯白区域的明暗表现。</p><div class="row"><input type="number"><span class="range"></span></div></div><div class="setting-group" data-key="power_line_frequency"><label>电源频率防闪烁</label><p>匹配照明电源频率以减少灯光条纹和闪烁；中国大陆通常选择 50 Hz。</p><div class="row"><select><option value="0">关闭</option><option value="1">50 Hz（中国大陆）</option><option value="2">60 Hz</option></select></div></div><div class="setting-group" data-key="white_balance_temperature"><label>白平衡色温</label><p>手动调整画面冷暖；数值低偏暖、高偏冷，仅在关闭自动白平衡后可用。</p><div class="row"><input type="number"><span class="range"></span></div></div><div class="setting-group" data-key="sharpness"><label>锐度</label><p>增强边缘清晰度；过高可能产生噪点和轮廓白边。</p><div class="row"><input type="number"><span class="range"></span></div></div></div><button id="applyImageButton" class="primary" onclick="applyImageSettings()">应用并保存画面参数</button><p id="imageMessage" class="muted"></p><div class="notice">保存位置：/home/root/configs/camera_config.json。保存时保留曝光、逆透视和其他已有字段。</div></section></main><script>
let frameTimer=null,heartbeatTimer=null,imageState=null;async function api(p,o){let r=await fetch(p,o);return r.json()}function toggleManual(){exposureTime.disabled=autoExposure.value==='true'}function renderExposure(c){autoExposure.value=String(c.auto_exposure);autoPriority.value=String(c.auto_priority);autoPriority.disabled=!c.auto_priority_available;exposureTime.value=c.exposure_time;exposureTime.min=c.exposure_min;exposureTime.max=c.exposure_max;exposureTime.step=c.exposure_step;exposureRange.innerText=`范围 ${c.exposure_min}～${c.exposure_max}，步进 ${c.exposure_step}`;cameraMessage.innerText=c.message+(c.auto_priority_available?'':'；当前摄像头不支持帧率/亮度优先控制');toggleManual()}function group(k){return document.querySelector(`[data-key="${k}"]`)}function control(k){return group(k).querySelector('input,select')}function renderImage(c){imageState=c;for(let k of ['brightness','contrast','saturation','hue','auto_white_balance','gamma','power_line_frequency','white_balance_temperature','sharpness']){let d=c[k],g=group(k),el=control(k);g.classList.toggle('unavailable',!d.available);if(!d.available)continue;el.value=d.value;el.disabled=d.inactive;if(el.tagName==='INPUT'){el.min=d.min;el.max=d.max;el.step=d.step;g.querySelector('.range').innerText=`范围 ${d.min}～${d.max}，步进 ${d.step}`}}imageMessage.innerText=c.message;toggleWhiteBalance()}function toggleWhiteBalance(){let awb=control('auto_white_balance'),temp=control('white_balance_temperature');if(!group('white_balance_temperature').classList.contains('unavailable'))temp.disabled=awb.value==='1'}function imageBody(){let keys=['brightness','contrast','saturation','hue','auto_white_balance','gamma','power_line_frequency','white_balance_temperature','sharpness'];return keys.filter(k=>imageState[k].available).map(k=>k+'='+encodeURIComponent(control(k).value)).join('&')}async function loadImageSettings(){renderImage(await api('/api/camera/image-settings'))}function reloadFrame(){cameraLive.src='/api/camera/frame?t='+Date.now()}async function heartbeat(){try{await api('/api/camera/preview/start',{method:'POST'})}catch(e){cameraMessage.innerText='无法连接摄像头服务'}}async function startPreview(){try{renderExposure(await api('/api/camera/preview/start',{method:'POST'}));await loadImageSettings()}catch(e){cameraMessage.innerText='无法连接摄像头服务'}reloadFrame();frameTimer=setInterval(reloadFrame,250);heartbeatTimer=setInterval(heartbeat,1500)}function stopPreview(){if(frameTimer)clearInterval(frameTimer);if(heartbeatTimer)clearInterval(heartbeatTimer);navigator.sendBeacon('/api/camera/preview/stop','')}async function applyExposureSettings(){applyExposureButton.disabled=true;let body='auto='+encodeURIComponent(autoExposure.value)+'&exposure='+encodeURIComponent(exposureTime.value)+'&priority='+encodeURIComponent(autoPriority.value);renderExposure(await api('/api/camera/settings',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}));applyExposureButton.disabled=false}async function applyImageSettings(){applyImageButton.disabled=true;try{renderImage(await api('/api/camera/image-settings',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:imageBody()}))}catch(e){imageMessage.innerText='画面参数应用失败'}applyImageButton.disabled=false}window.addEventListener('pagehide',stopPreview);startPreview();
</script></body></html>)HTML";
}

} // namespace web_pages
